DROP TABLE IF EXISTS `qd_home_user`;
CREATE TABLE `qd_home_user`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `lang` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `nick_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `true_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `alipay` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `mobile` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `phone_code` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '手机区号',
  `password` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `paypwd` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `user_money` decimal(20, 4) NOT NULL DEFAULT 0.0000 COMMENT '基础钱包(可转换到收益)',
  `tyj_money` decimal(20, 4) NOT NULL DEFAULT 0.0000 COMMENT '体验金额(不可提现）',
  `frozen_money` decimal(20, 4) UNSIGNED NOT NULL DEFAULT 0.0000 COMMENT '提现冻结金额（提现审核中的金额）',
  `recharge_money` decimal(20, 4) UNSIGNED NOT NULL DEFAULT 0.0000 COMMENT '充值钱包',
  `brokerage_money` decimal(20, 4) UNSIGNED NOT NULL DEFAULT 0.0000 COMMENT '佣金金额（可直接提现）',
  `earnings_money` decimal(20, 4) UNSIGNED NOT NULL DEFAULT 0.0000 COMMENT '总收益(佣金累计）',
  `points` decimal(20, 4) NOT NULL DEFAULT 100.0000 COMMENT '用户积分',
  `balance_money` decimal(20, 4) NOT NULL DEFAULT 0.0000 COMMENT '余额宝存储',
  `brokerage_pool` decimal(20, 4) UNSIGNED NOT NULL DEFAULT 0.0000 COMMENT '佣金池',
  `withdrawal_amount` decimal(20, 4) UNSIGNED NOT NULL DEFAULT 0.0000 COMMENT '总提现金额',
  `water_money` decimal(20, 4) NOT NULL DEFAULT 0.0000 COMMENT '用户流水',
  `level_id` int NOT NULL DEFAULT 0 COMMENT '等级id',
  `plan_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '计划任务id',
  `finance_plan_id` int UNSIGNED NOT NULL DEFAULT 0,
  `ad_plan_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '广告位计划id',
  `user_water_status` tinyint NOT NULL DEFAULT 1 COMMENT '0-不限制 1-默认 2-限制',
  `bank_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `bank_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `bank_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `document_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `document_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `bank_kh` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `bank_address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `qqnum` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `login_times` int NOT NULL DEFAULT 0 COMMENT '登陆次数',
  `last_login_ip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `last_login_time` int NOT NULL DEFAULT 0 COMMENT '最后登录时间',
  `invite_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `invite_code_status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '邀请码状态 0-禁用 1-正常',
  `status` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '状态',
  `is_activate` tinyint(1) NOT NULL DEFAULT 0 COMMENT '激活状态 0-未激活 1-已激活',
  `create_time` int NOT NULL DEFAULT 0 COMMENT '注册时间',
  `update_time` int NULL DEFAULT NULL COMMENT '更新时间',
  `leader1` int NOT NULL DEFAULT 0,
  `leader2` int NOT NULL DEFAULT 0,
  `leader3` int NOT NULL DEFAULT 0,
  `leader4` int NOT NULL DEFAULT 0,
  `leader5` int NOT NULL DEFAULT 0,
  `leader6` int NOT NULL DEFAULT 0,
  `leader7` int NOT NULL DEFAULT 0,
  `is_xuni` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '虚拟用户',
  `is_rec` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推荐',
  `is_demo` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否是DEMO',
  `ip` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `login_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `tree_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `bsc_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `recharge_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `withdraw_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `bsc_withdraw_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `usdt_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `usdt` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `delete_time` int NULL DEFAULT NULL COMMENT '删除时间',
  `cp_id` int NULL DEFAULT 0 COMMENT 'CP ID',
  `pd_num` int UNSIGNED NULL DEFAULT 0 COMMENT '拼单次数限制',
  `is_upgrade` tinyint(1) NULL DEFAULT 0 COMMENT '是否需要升级后做任务 0不需要 1需要',
  `upgrade_status` tinyint(1) NULL DEFAULT 0 COMMENT '是否已经升级 0未升级 1已升级',
  `task_count` int NULL DEFAULT 0 COMMENT '可以完成任务次数',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `withdraw_status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '提现状态 1开启 0禁止',
  `withdraw_rec_count` int NULL DEFAULT 0 COMMENT '累计推荐人数限制',
  `withdraw_rec_recharge` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '累计下级充值限制',
  `kyc_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'kyc状态',
  `is_proxy` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否代理',
  `is_total_proxy` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否总代理',
  `show_virtual_data` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否显示假数据',
  `do_task_status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '做任务开关',
  `is_invite_do_task` tinyint(1) NOT NULL DEFAULT 0 COMMENT '邀请用户才能做任务',
  `invite_do_task_num` int NOT NULL DEFAULT 0 COMMENT '邀请几个用户',
  `invite_do_task_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '邀请用户充值满多少',
  `sign_in_day` int NOT NULL DEFAULT 0 COMMENT '已签到天数',
  `sign_last_time` int NOT NULL DEFAULT 0 COMMENT '最后签到时间',
  `lottery_num` int NOT NULL DEFAULT 1 COMMENT '注册抽奖次数',
  `lottery_num_invite` int NOT NULL DEFAULT 0 COMMENT '邀请抽奖次数',
  `credit_score` int NOT NULL DEFAULT 0 COMMENT '信用分',
  `one_task_buckle` int NOT NULL DEFAULT 0 COMMENT '分配一次任务扣多少分',
  `buckle_score_num` int NOT NULL DEFAULT 0 COMMENT '总共扣几次',
  `usdt_address_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT 'usdt余额',
  `trx_address_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT 'trx余额',
  `withdraw_max_usdt` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '最大提现金额（USDT)',
  `pix` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '推广像素id',
  `platform` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '推广平台',
  `click_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT 'kwai 点击事件id',
  `team_info_month_reset` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '团队数据是否每月重新统计 0-不重置 1-重置',
  `is_credit_score` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否开启信用评分机制 0-不开启 1-开启',
  `is_finance_product_count_down` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否开启流量包缓冲倒计时的阶段 0-不开启 1-开启',
  `finance_product_button_count_down` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '广告位缓冲倒计时按钮loading时长',
  `team_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '团队总人数',
  `transfer_money_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否可以转账给其他用户',
  `withdrawal_money` decimal(20, 4) UNSIGNED NOT NULL DEFAULT 0.0000,
  `reward_multiplier` float(8, 2) NULL DEFAULT 1.00 COMMENT '活动奖励倍数',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_user_name`(`user_name` ASC) USING BTREE,
  INDEX `idx_mobile`(`mobile` ASC) USING BTREE,
  INDEX `idx_is_xuni`(`is_xuni` ASC) USING BTREE,
  INDEX `idx_leader1`(`leader1` ASC) USING BTREE,
  INDEX `idx_tree_id`(`tree_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 119507 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

